use xiom.io;

use xiom.string;
module shapes {
  pub interface Area {
    fn area() -> Int;
  }

  pub type Rectangle = {
    width: Int;
    height: Int;
  }

  pub fn Rectangle.area(self) -> Int {
    return self.width * self.height;
  }

  pub type Circle = {
    radius: Int;
  }

  pub fn Circle.area(self) -> Int {
    return 3 * self.radius * self.radius;
  }

  pub fn total_area[T: Area](items: &Vec[T]) -> Int {
    let total = 0;
    let i = 0;
    while i < items.len() {
      let item = match items.get(i) { Some(v) => v, None => { i = i + 1; continue; } };
      total = total + item.area();
      i = i + 1;
    }
    return total;
  }
}

fn main() -> Int {
  let rects: Vec<shapes.Rectangle> = Vec[shapes.Rectangle].new();
  rects.push(shapes.Rectangle{ width: 3, height: 4 });
  rects.push(shapes.Rectangle{ width: 5, height: 2 });
  io.println(to_string(shapes.total_area(&rects)));
  return 0;
}
